import test from 'node:test';
import assert from 'node:assert/strict';
import {createService,validateContent,publicProjection} from '../server/service.mjs';
import {createHttpHandler} from '../server/server.mjs';
import {renderPublic} from '../server/render.mjs';
import http from 'node:http';

function setup(options={}){
  const data=new Map();let lock=Promise.resolve(),sends=0;
  const clone=value=>value===undefined?null:structuredClone(value);
  const store={get:async path=>clone(data.get(path)),set:async(path,value)=>data.set(path,clone(value)),list:async collection=>[...data.entries()].filter(([path])=>path.startsWith(collection+'/')).map(([,v])=>clone(v)),atomic(fn){const run=lock.then(async()=>{const copy=new Map([...data].map(([k,v])=>[k,clone(v)]));const result=await fn({get:async p=>clone(copy.get(p)),set:(p,v)=>copy.set(p,clone(v)),delete:p=>copy.delete(p)});data.clear();for(const pair of copy)data.set(...pair);return result;});lock=run.catch(()=>{});return run;}};
  const service=createService({store,verifyOwner:async token=>{if(token!=='owner-token')throw Error();},verifyApp:async token=>{if(token!=='app-token')throw Error();},mail:{configured:true,send:async()=>{sends++;if(options.mailFails)throw Error();return'provider-reference';}},config:{rateSalt:'isolated-test-fixture'},now:()=>Date.parse('2026-10-20T12:00:00Z'),random:()=>'test-only-edit-key',...options});
  const call=(method,path,body={},headers={})=>service({method,path,body,headers:{'x-firebase-appcheck':'app-token',...headers},ip:'isolated-test-address'});
  return{service,store,data,call,sends:()=>sends};
}
const challenge={title:'Isolated test suggestion',text:'This fixture never enters the public website.',displayName:'Test',consent:true,website:''};
const contact={name:'Test',email:'fixture@example.invalid',brand:'',format:'Test',message:'This message must never be sent by a real provider.',consent:true,website:''};
const key='isolated-request-id-00001';
const owner={authorization:'Bearer owner-token'};
test('public suggestions start private; public projection excludes edit key',async()=>{const s=setup(),result=await s.call('POST','/api/challenges',challenge,{'idempotency-key':key});assert.equal(result.body.moderation,'pending');assert.equal((await s.call('GET','/api/public')).body.records.length,0);const draft=[...s.data.values()].find(v=>v.kind==='challenge');assert.ok(draft.editHash);assert.ok(!JSON.stringify(draft).includes(result.body.editKey));});
test('unauthenticated owner calls and invalid App Check fail closed',async()=>{const s=setup();await assert.rejects(s.call('GET','/api/content'),e=>e.status===401);await assert.rejects(s.call('POST','/api/challenges',challenge,{'x-firebase-appcheck':'invalid','idempotency-key':key}),e=>e.status===403);});
test('publication, result, revision conflicts, withdrawal and public edit re-review',async()=>{const s=setup(),submission=await s.call('POST','/api/challenges',challenge,{'idempotency-key':key}),id=submission.body.id,content=validateContent('challenge',{title:challenge.title,text:challenge.text,displayName:challenge.displayName});await s.call('POST','/api/content',{id,kind:'challenge',content,revision:1,action:'publish'},owner);let publicData=(await s.call('GET','/api/public')).body.records;assert.equal(publicData.length,1);assert.equal(publicData[0].lifecycle,'proposed');assert.ok(!JSON.stringify(publicData).includes('editHash'));await assert.rejects(s.call('POST','/api/content',{id,kind:'challenge',content,revision:1,action:'publish'},owner),e=>e.status===409);await s.call('PATCH','/api/challenges/'+id,content,{'x-edit-key':submission.body.editKey});assert.equal((await s.call('GET','/api/public')).body.records.length,0);assert.equal((await s.store.get('journeyDrafts/'+id)).moderation,'pending');await assert.rejects(s.call('POST','/api/content',{id,kind:'challenge',content,revision:3,action:'publish',lifecycle:'completed'},owner),e=>e.status===400);await s.call('POST','/api/content',{id,kind:'challenge',content,revision:3,action:'publish',lifecycle:'completed',result:'Actual fixture result for the isolated test.'},owner);assert.equal((await s.call('GET','/api/public')).body.records[0].lifecycle,'completed');await s.call('POST','/api/content',{id,kind:'challenge',content,revision:4,action:'unpublish'},owner);assert.equal((await s.call('GET','/api/public')).body.records.length,0);});
test('challenge edit keys cannot edit another submission',async()=>{const s=setup(),r=await s.call('POST','/api/challenges',challenge,{'idempotency-key':key});await assert.rejects(s.call('PATCH','/api/challenges/'+r.body.id,{title:challenge.title,text:challenge.text,displayName:''},{'x-edit-key':'wrong'}),e=>e.status===403);});
test('server lengths, consent, honeypot, unknown fields and rate limits',async()=>{const s=setup();for(const body of [{...challenge,text:'short'},{...challenge,consent:false},{...challenge,website:'bot'},{...challenge,status:'published'}])await assert.rejects(s.call('POST','/api/challenges',body,{'idempotency-key':key}),e=>e.status===400);for(let i=0;i<5;i++)await s.call('POST','/api/challenges',challenge,{'idempotency-key':key+i});await assert.rejects(s.call('POST','/api/challenges',challenge,{'idempotency-key':key+'six'}),e=>e.status===429);});
test('contact retries and concurrent clicks send once',async()=>{const s=setup();const results=await Promise.all(Array.from({length:3},()=>s.call('POST','/api/contact',contact,{'idempotency-key':key})));assert.equal(s.sends(),1);assert.ok(results.every(r=>r.status===202));await assert.rejects(s.call('POST','/api/contact',{...contact,message:'A different test message.'},{'idempotency-key':key}),e=>e.status===409);});
test('missing provider never claims sent; ambiguous sends are held without resend',async()=>{const missing=setup({mail:{configured:false}});await assert.rejects(missing.call('POST','/api/contact',contact,{'idempotency-key':key}),e=>e.status===503);assert.equal(missing.data.size,0);const s=setup({mailFails:true});await s.call('POST','/api/contact',contact,{'idempotency-key':key});await s.call('POST','/api/contact',contact,{'idempotency-key':key});assert.equal(s.sends(),1);assert.ok([...s.data.values()].some(v=>v.state==='held-for-review'));});
test('no future departure confirmations or future sent editions',async()=>{const s=setup();await assert.rejects(s.call('POST','/api/content',{id:'fixture-trip',kind:'trip',content:{confirmedDepartureAt:'2026-10-28T00:00:00+01:00',endedAt:null},action:'publish'},owner),e=>e.status===400);await assert.rejects(s.call('POST','/api/content',{id:'fixture-postcard',kind:'postcard',content:{title:'Fixture',subtitle:'Only in tests',sentDate:'2026-10-28',paragraphs:['Fixture text'],destinationIds:[],storyUrls:[]},action:'publish'},owner),e=>e.status===400);});
test('publication timestamp is server-owned, draft content does not leak',async()=>{const s=setup(),content={title:'Fixture note',text:'Private text in isolated tests.',eventDate:'2026-10-01',destinationId:'thailand',tripId:'test-trip'};await s.call('POST','/api/content',{id:'fixture-note',kind:'journal',content,action:'save'},owner);assert.equal((await s.call('GET','/api/public')).body.records.length,0);await s.call('POST','/api/content',{id:'fixture-note',kind:'journal',content,revision:1,action:'publish'},owner);const record=(await s.call('GET','/api/public')).body.records[0];assert.equal(record.publishedAt,'2026-10-20T12:00:00.000Z');assert.equal(record.eventDate,'2026-10-01');assert.equal(record.url,'note-fixture-note.html');assert.equal(publicProjection({moderation:'draft'}),null);});
test('public rendering escapes text and never renders private records',()=>{assert.equal(renderPublic({status:'draft'},{}),null);const html=renderPublic({status:'published',kind:'journal',title:'<script>bad</script>',text:'<img onerror=bad>',url:'note-test.html',publishedAt:'2026-10-20',eventDate:'2026-10-01'},{header:'',footer:''});assert.ok(!html.includes('<script>bad'));assert.ok(html.includes('&lt;img onerror=bad&gt;'));});
test('server validates expense precision, private fields and actual dates',()=>{for(const amountMinor of [1.5,-1,Infinity,Number.MAX_SAFE_INTEGER])assert.throws(()=>validateContent('expense',{amountMinor,personalMinor:1,currency:'EUR',date:'2026-10-01',tripId:'test',destinationId:'test',category:'Food',coverageNote:'Test only'}));assert.throws(()=>validateContent('checkin',{city:'Test',country:'Test',eventDate:'2026-02-30',tripId:'test'}));assert.throws(()=>validateContent('journal',{title:'Test',text:'Private text',eventDate:'2026-10-01',destinationId:'test',tripId:'test',email:'private'}));});
test('publishing dates use the reporting timezone and journey end follows departure',async()=>{const s=setup({now:()=>Date.parse('2026-10-20T23:30:00Z')});await s.call('POST','/api/content',{id:'fixture-midnight',kind:'checkin',content:{city:'Test',country:'Test',eventDate:'2026-10-21',tripId:'test'},action:'publish'},owner);assert.throws(()=>validateContent('trip',{confirmedDepartureAt:'2026-10-20T00:00:00Z',endedAt:'2026-10-19T00:00:00Z'}));});
test('HTTP runtime rejects cross-origin, wrong content type, malformed and oversized bodies',async()=>{
  const s=setup();const server=http.createServer(createHttpHandler(s.service,{origins:['http://test.invalid'],publicWrites:true,publishing:true}));await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port;
  try{
    assert.equal((await fetch(base+'/api/challenges',{method:'POST',headers:{origin:'http://evil.invalid','content-type':'application/json'},body:'{}'})).status,403);
    assert.equal((await fetch(base+'/api/challenges',{method:'POST',headers:{origin:'http://test.invalid','content-type':'text/plain'},body:'{}'})).status,415);
    assert.equal((await fetch(base+'/api/challenges',{method:'POST',headers:{origin:'http://test.invalid','content-type':'application/json'},body:'broken'})).status,400);
    assert.equal((await fetch(base+'/api/challenges',{method:'POST',headers:{origin:'http://test.invalid','content-type':'application/json'},body:'x'.repeat(17000)})).status,413);
  }finally{await new Promise(r=>server.close(r));}
});
